export default function TechStackIcon({ iconName, className = "" }: { iconName: string, className?: string }) {
  // Normalize the iconName (e.g. "Hugging Face" -> "huggingface", "Node.js" -> "nodedotjs", "AWS" -> "aws")
  const normKey = iconName
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .replace('golang', 'go')
    .replace('amazonwebservices', 'aws');
    
  const icon = svgMap[normKey];
  
  if (!icon) {
    // Return a fallback empty box or placeholder if icon is not found
    return (
      <svg viewBox="0 0 24 24" className={className} fill="currentColor">
        <rect x="2" y="2" width="20" height="20" rx="4" fill="none" stroke="currentColor" strokeWidth="2" />
        <path d="M12 8v8M8 12h8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      </svg>
    );
  }

  return (
    <svg
      viewBox={icon.viewBox}
      className={`${className} fill-current`}
      dangerouslySetInnerHTML={{ __html: icon.content }}
    />
  );
}
